      "name": "Compound Annual Growth Rate (CAGR)",
      "description": "Annualized growth rate of the closing price over the full dataset period."
    },
    {
      "name": "Maximum Drawdown",
      "description": "The largest peak-to-trough decline in closing price observed during the dataset period."
